INSERT INTO `v1_7befd9874e874741c941c505d2815e8f2dfcd53e51a278232e2eaa6266373712` VALUES ("vo_minigame_1004_top_1_000", "ふっふっふ、これでカヤぴぃとボスを見返してやるです！", 2, 1, "vo_minigame_1004", 1000101, 10001);
